bool compression_worthwhile(std::string_view raw, void* context) {
  if (raw.size() < 16 * 1024) return true;
  constexpr size_t span = 2048;
  std::array<char, span * 4> sample;
  for (size_t index = 0; index < 4; ++index)
    memcpy(sample.data() + index * span, raw.data() + (raw.size() - span) * index / 3, span);
  std::array<char, ZSTD_COMPRESSBOUND(span * 4)> compressed;
  size_t size = ZSTD_compressCCtx((ZSTD_CCtx*)context, compressed.data(), compressed.size(), sample.data(), sample.size(), 1);
  return ZSTD_isError(size) || size < sample.size() * 95 / 100;
}

bool zstd_level_supported(int level) {
  return level >= ZSTD_minCLevel() && level <= ZSTD_maxCLevel();
}

bool zstd_window_log_supported(int window_log) {
  return window_log >= ZSTD_WINDOWLOG_MIN && window_log <= ZSTD_WINDOWLOG_MAX;
}

bool zstd_configure_compressor(void* context, int level, bool long_mode, int window_log) {
  ZSTD_CCtx* cctx = (ZSTD_CCtx*)context;
  if (!cctx || !zstd_level_supported(level)) return false;
  if (ZSTD_isError(ZSTD_CCtx_setParameter(cctx, ZSTD_c_compressionLevel, level))) return false;
  if (long_mode) {
    if (!zstd_window_log_supported(window_log)) return false;
    if (ZSTD_isError(ZSTD_CCtx_setParameter(cctx, ZSTD_c_enableLongDistanceMatching, 1))) return false;
    if (ZSTD_isError(ZSTD_CCtx_setParameter(cctx, ZSTD_c_windowLog, window_log))) return false;
  }
  return true;
}

bool zstd_configure_decompressor(void* context, bool long_mode, int window_log) {
  ZSTD_DCtx* dctx = (ZSTD_DCtx*)context;
  if (!dctx) return false;
  if (long_mode) {
    if (!zstd_window_log_supported(window_log)) return false;
    if (ZSTD_isError(ZSTD_DCtx_setParameter(dctx, ZSTD_d_windowLogMax, window_log))) return false;
  }
  return true;
}

